package android.graphics;public class Canvas {private final java.awt.Graphics2D g;public Canvas(Bitmap b){g=b.pixels.createGraphics();g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);}public void scale(float x,float y){g.scale(x,y);}public void drawColor(int c){java.awt.geom.AffineTransform t=g.getTransform();g.setTransform(new java.awt.geom.AffineTransform());g.setColor(new java.awt.Color(c,true));g.fillRect(0,0,1<<15,1<<15);g.setTransform(t);}public void drawText(String s,float x,float y,Paint p){if(s.isEmpty())return;g.setFont(p.font());g.setColor(new java.awt.Color(p.color,true));g.drawString(s,x,y);}}
